(function(){
  'use strict';
  const C=AcademyCurriculum,V=AcademyVisuals,M=AcademyModel,A=AcademyAudio;
  const $=(s,el=document)=>el.querySelector(s),$$=(s,el=document)=>[...el.querySelectorAll(s)];
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const storage={get(k){try{return localStorage.getItem('gr-academy-'+k);}catch{return null;}},set(k,v){try{localStorage.setItem('gr-academy-'+k,v);}catch{}}};
  let progress=M.readProgress(storage.get('progress'),C.map(c=>c.id));
  let settings={effects:matchMedia('(prefers-reduced-motion: reduce)').matches?'light':'full',volume:.25};
  try{const p=JSON.parse(storage.get('settings'));if(p&&['full','light','off'].includes(p.effects))settings.effects=p.effects;if(p&&Number.isFinite(p.volume))settings.volume=Math.max(0,Math.min(1,p.volume));}catch{}
  let shared={kind:'scf',reference:'r',unit:'kcal',projectName:'',recipe:false};
  try{const p=JSON.parse(storage.get('sample-state'));if(p&&['scf','g'].includes(p.kind)&&['r','i'].includes(p.reference)&&['kcal','kj','eh'].includes(p.unit)){shared={kind:p.kind,reference:p.reference,unit:p.unit,projectName:typeof p.projectName==='string'?p.projectName.slice(0,60):'',recipe:p.recipe===true};}}catch{}
  function saveShared(){storage.set('sample-state',JSON.stringify(shared));}
  let route='overview',chapter=null,step=0,events=new Set(),feedback='',toastTimer;
  let hero={selected:'ts',compare:false,dimension:'2d'},lab={};
  function freshLab(){return M.withSavedScience({created:false,name:'未命名项目',saved:false,imported:false,job:'1',evidence:false,species:[],role:'',coefficient:1,kind:'scf',reference:'none',unit:'kcal',selected:'r',compare:false,color:'#bda6e9',dimension:'2d',loaded:false,yaw:.42,pitch:.35,zoom:1,atom:-1,query:'',freq:null,field:'',nboformat:'supported',nboTab:'npa',point:0,branch:'forward',theme:'dark',language:'zh',motion:false,format:'png',recovery:'changed',row:null,thermoChoice:'correction'},shared,chapter?.id);}
  function save(){storage.set('progress',JSON.stringify(progress));}
  function persistSettings(){storage.set('settings',JSON.stringify(settings));}
  function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3000);}
  function act(name,message){events.add(name);if(message)feedback=message;updateGuide();A.play('click');}
  function button(text,action,cls='',icon=''){return `<button class="button ${cls}" data-action="${action}">${icon?V.icon(icon):''}${text}</button>`;}
  function badge(text,cls=''){return `<span class="pill ${cls}">${text}</span>`;}
  function status(text){return `<div class="inline-status" role="status">${text}</div>`;}
  function go(id){location.hash=id==='overview'?'overview':id;if(route===id)renderRoute();}
  function nav(){
    const pct=Math.round(progress.done.length/C.length*100);let prev='';
    $('#sidebar').innerHTML=`<button class="mobile-close" data-action="close-nav" aria-label="关闭导航">${V.icon('close')}</button><a class="brand" href="#overview" aria-label="GaussianReaderPro Academy 首页"><span class="brand-mark">${V.icon('chart')}</span><span class="brand-name">GaussianReaderPro<small>ACADEMY</small></span></a><nav class="nav-scroll"><a href="#overview" class="nav-item ${route==='overview'?'active':''}">${V.icon('book')}学习概览<span class="nav-count">⌘</span></a>${C.map((c,i)=>{let group=c.group!==prev?`<div class="nav-group">${c.group}</div>`:'';prev=c.group;return group+`<a href="#${c.id}" class="nav-item ${route===c.id?'active':''}" ${route===c.id?'aria-current="page"':''}>${V.icon(c.icon)}${c.short}${progress.done.includes(c.id)?V.icon('check','nav-check'):`<span class="nav-count">${String(i+1).padStart(2,'0')}</span>`}</a>`;}).join('')}</nav><div class="side-progress"><div class="side-progress-top"><span>你的学习旅程</span><span>${progress.done.length} / ${C.length}</span></div><div class="progress-track" role="progressbar" aria-valuenow="${pct}" aria-valuemin="0" aria-valuemax="100" aria-label="学习完成度"><i style="width:${pct}%"></i></div><div class="side-bottom">${V.icon('heart')}每一次探索，都让理解更进一步</div></div>`;
  }
  function topbar(){
    $('#topbar').innerHTML=`<div class="breadcrumb"><button class="icon-button mobile-menu" data-action="open-nav" aria-label="展开课程导航">${V.icon('menu')}</button><span>交互学习中心</span>${V.icon('chevron')}<strong>${chapter?chapter.short:'学习概览'}</strong><span class="version-badge">V 2.0</span></div><div class="top-controls"><button class="search-trigger" data-action="search" aria-label="搜索课程和操作">${V.icon('search')}<span>搜索课程、操作…</span><kbd>Ctrl K</kbd></button><button class="icon-button" id="audio-toggle" data-action="audio" aria-label="${A.isEnabled()?'关闭音效':'开启音效'}" title="${A.isEnabled()?'关闭音效':'开启音效'}">${V.icon(A.isEnabled()?'volume':'mute')}</button><button class="icon-button" data-action="preferences" aria-label="外观与声音设置" title="外观与声音设置">${V.icon('settings')}</button></div>`;
  }
  function currentEnergy(n,config){const kind=config.kind||'scf',r=V.nodes.find(x=>x.id===config.reference)||V.nodes[0];return M.relativeEnergy(kind==='g'?n.g:n.energy,kind==='g'?r.g:r.energy,config.unit||'kcal');}
  function detail(config){const n=V.nodes.find(n=>n.id===config.selected)||V.nodes[2],e=currentEnergy(n,config);return `<div class="node-avatar">${n.label}</div><div><strong>${n.desc} · ${n.label}</strong><small>${n.source} · 教学示例</small></div><div class="energy-value">${e.toFixed((config.unit||'kcal')==='eh'?4:2)}<small>${{kcal:'kcal/mol',kj:'kJ/mol',eh:'Hartree'}[config.unit||'kcal']}</small></div>`;}
  function moduleCard(c,i){return `<a class="module-card glass" href="#${c.id}" style="--card-accent:${i%3===1?'#c0a9e7':i%3===2?'#e5bd85':'#9ddbc1'}"><div class="module-top"><span class="module-icon ${i%3===1?'purple':i%3===2?'amber':''}">${V.icon(c.icon)}</span><span class="module-no">${progress.done.includes(c.id)?'✓ 已完成':String(i+1).padStart(2,'0')}</span></div><h3>${c.short}</h3><p>${c.intro}</p><div class="module-bottom"><span>${c.time} · ${c.tag}</span>${V.icon('arrow')}</div></a>`;}
  function home(){
    const next=C.find(c=>c.id===progress.last&&!progress.done.includes(c.id))||C.find(c=>!progress.done.includes(c.id))||C[0];
    $('#main').innerHTML=`<div class="animate-in"><section class="hero"><div class="hero-copy"><div class="eyebrow">${V.icon('spark')}A LITTLE CURIOSITY. A CLEARER PICTURE.</div><h1>让每一次计算，<br><span class="gradient-word">都清晰可见。</span></h1><p>从第一份 Gaussian 日志，到完整的反应能量剖面。<br>在这里，亲手探索 GaussianReaderPro 的每一种可能。</p><div class="hero-actions"><a class="button primary" href="#${next.id}">${V.icon('play')}${progress.done.length?'继续交互学习':'开始交互学习'}${V.icon('arrow')}</a><a class="button text" href="#modules" data-action="explore">探索全部模块 ${V.icon('chevron')}</a></div><div class="hero-footnote">${V.icon('check')}无需准备文件 · 内置教学示例 · 随时继续</div></div><div class="hero-art"><div class="orbital-halo"></div><i class="orbit-dot"></i><div class="hero-molecule" id="hero-molecule">${V.molecule({yaw:.5,pitch:.45})}</div><div class="float-label glass one"><span class="label-icon">${V.icon('molecule')}</span><span><small>MOLECULAR INSIGHT</small><strong>从数值，走近结构</strong></span></div><div class="float-label glass two"><span class="label-icon">${V.icon('chart')}</span><span><small>EVERY STEP CONNECTED</small><strong>让反应路径一目了然</strong></span></div><div class="art-caption">SCIENTIFIC CURIOSITY, BEAUTIFULLY EXPLORED.</div></div></section><div class="overview-stats"><span>${V.icon('book')}<strong>14</strong> 个探索主题</span><span>${V.icon('network')}<strong>42</strong> 个动手步骤</span><span>${V.icon('spark')}按自己的节奏，随时启程</span></div><section class="feature-grid"><div class="panel glass"><div class="panel-head"><div><div class="panel-kicker">A GLIMPSE INTO YOUR REACTION</div><h2 class="panel-title">一条曲线，读懂反应。</h2><p class="panel-sub">点一点节点，看看每一步发生了什么</p></div>${badge('● 实时交互')}</div><div class="chart-toolbar"><div class="segmented"><button class="${hero.dimension==='2d'?'active':''}" data-action="hero-2d">2D</button><button class="${hero.dimension==='3d'?'active':''}" data-action="hero-3d">立体示意</button></div><div class="chart-legend"><span>路径 A</span>${hero.compare?'<span class="alt">路径 B</span>':''}<button style="background:none;color:inherit;padding:0;font-size:9px" data-action="hero-compare">${hero.compare?'隐藏对比':'＋ 对比路径'}</button></div></div><div class="chart-wrap" id="hero-chart">${V.chart(hero)}</div><div class="node-detail" id="hero-detail">${detail(hero)}</div></div><div class="continue-panel panel glass"><div class="panel-kicker">${progress.done.length?'CONTINUE YOUR JOURNEY':'YOUR FIRST SMALL DISCOVERY'}</div><div class="continue-icon">${V.icon(next.icon)}</div><h3>${next.title}</h3><p>${next.intro} 跟着清晰的提示，在操作中建立理解。</p><div class="lesson-meta"><span>${V.icon('clock')}${next.time}</span><span>3 个交互步骤</span><span>随时重练</span></div><div class="progress-track"><i style="width:${progress.done.length/C.length*100}%"></i></div><a class="button primary" href="#${next.id}">${progress.done.length?'接着学':'进入第一课'}${V.icon('arrow')}</a></div></section><section id="modules"><div class="section-heading"><div><h2>你的工作台，逐一解锁。</h2><p>不止知道在哪里，更知道怎么用、为什么。</p></div><button class="text-link" style="background:none;padding:0" data-action="show-all">${storage.get('showall')==='yes'?'收起课程':'全部 14 个主题'}${V.icon('arrow')}</button></div><div class="module-grid" id="module-grid">${(storage.get('showall')==='yes'?C:C.slice(0,6)).map(moduleCard).join('')}</div></section><div class="bottom-note glass">${V.icon('spark')}<div><strong>让每一个数值，都有来处。</strong>本教程使用合成示例；真实研究始终以原始日志与来源核验为准。</div><a class="button" href="#log">学习来源追溯 ${V.icon('arrow')}</a></div></div>`;
  }
  function course(){
    const index=C.indexOf(chapter);
    $('#main').innerHTML=`<div class="animate-in"><div class="lesson-title-row"><div><div class="eyebrow">CHAPTER ${String(index+1).padStart(2,'0')} / ${String(C.length).padStart(2,'0')} · ${chapter.tag}</div><h1>${chapter.title}</h1><p>${chapter.intro}</p></div><button class="button small" data-action="restart">${V.icon('reset')}重新练习</button></div><div class="lesson-layout"><section class="lab-panel panel glass"><div class="lab-header"><strong><span class="window-dots"><i></i><i></i><i></i></span>${V.icon(chapter.icon)}${chapter.short} · 交互操作台</strong>${badge('教学模拟','amber')}</div><div class="lab-content" id="lab"></div></section><aside class="instruction-panel glass" id="guide" aria-label="分步教学"></aside></div><div class="tips-section"><section class="tips-panel glass"><h2>${V.icon('spark')}在真正的软件里，记住这些</h2><ul>${chapter.tips.map(t=>`<li>${t}</li>`).join('')}</ul><div class="lesson-source">内容依据：GaussianReaderPro 2.0.0 实际界面与操作流程</div></section><section class="tips-panel knowledge-panel glass"><h2>${V.icon('book')}30 秒，确认一下理解</h2><p>${chapter.question}</p><div class="quiz-options">${chapter.answers.map((a,i)=>`<button class="quiz-choice" data-quiz="${i}">${String.fromCharCode(65+i)} · ${a}</button>`).join('')}</div><div class="quiz-result" id="quiz-result" aria-live="polite"></div></section></div></div>`;
    renderLab();updateGuide();
  }
  function updateGuide(){
    if(!chapter||!$('#guide'))return;
    if(step>=chapter.steps.length){$('#guide').innerHTML=`<div class="complete-banner">${V.icon('check')}<h3>这一站，已掌握。</h3><p>你完成了 ${chapter.short} 的 3 个操作目标。可以继续探索，也可以随时回来重练。</p><a class="button primary" href="#${C[C.indexOf(chapter)+1]?.id||'overview'}">${C[C.indexOf(chapter)+1]?'下一主题':'返回学习概览'}${V.icon('arrow')}</a></div>`;return;}
    const ready=events.has(chapter.steps[step][0]);
    $('#guide').innerHTML=`<div class="step-overline">LEARN BY DOING · ${step+1} / 3</div><ol class="step-list">${chapter.steps.map((s,i)=>`<li class="step-item ${i<step?'complete':i===step?'current':''}"><span class="step-number">${i<step?V.icon('check'):String(i+1).padStart(2,'0')}</span><div><h3>${s[1]}</h3>${i===step?`<p>${s[2]}</p>`:''}</div></li>`).join('')}</ol><div class="step-feedback ${ready?'ready':''}" aria-live="polite">${ready?'✓ 目标已完成，可以继续。':esc(feedback||'在左侧操作台亲手试一试，完成目标后继续。')}</div><button class="button primary" data-action="next-step" ${ready?'':'disabled'}>${step===2?'完成本课':'继续下一步'}${V.icon('arrow')}</button><div class="entry-note"><strong>在软件中从这里进入</strong>${chapter.entry}</div>`;
  }
  function stepNext(){if(step>=3||!events.has(chapter.steps[step][0]))return;step++;feedback='';if(step===3){if(!progress.done.includes(chapter.id))progress.done.push(chapter.id);save();nav();A.play('success');toast('已完成「'+chapter.short+'」，学习进度已保存。');}else A.play('switch');updateGuide();}
  const freqRows=[[-426.38,198.6,201,'虚频'],[526.12,12.4,201,'正常'],[842.75,38.2,201,'正常'],[1286.4,73.9,205,'正常'],[1621.8,114.5,205,'正常'],[3056.2,22.7,209,'正常']];
  const evidence=M.exampleEvidence;
  const thermoRows=[['SCF 电子能',evidence.scf.toFixed(6),'Eh','L128'],['零点能校正','0.052100','Eh','L310'],['Gibbs 热校正',evidence.correction.toFixed(6),'Eh','L313'],['总自由能 G',evidence.g.toFixed(6),'Eh','L317']];
  const logLines=[[101,' Entering Link 1 = Gaussian 16'],[102,' # B3LYP/6-31G(d) Opt Freq'],[103,' Charge = 0 Multiplicity = 1'],[120,' Standard orientation:'],[121,' Center   Atomic Number       X          Y          Z'],[122,' 1          6             -1.3000     0.0000     0.0000'],[128,` SCF Done: E(RB3LYP) = ${evidence.scf.toFixed(6)} A.U.`],[201,' Frequencies -- -426.3800   526.1200   842.7500'],[313,` Thermal correction to Gibbs Free Energy= ${evidence.correction.toFixed(6)}`],[317,` Sum of electronic and thermal Free Energies= ${evidence.g.toFixed(6)}`],[350,' Normal termination of Gaussian 16.']];
  function table(headers,rows,attrs=''){return `<div class="table-scroll"><table class="data-table" ${attrs}><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')||`<tr><td colspan="${headers.length}" class="empty-results">没有匹配行，请修改筛选条件。</td></tr>`}</tbody></table></div>`;}
  function selector(){return `<div class="control-row"><label>来源<select id="analysis-source"><option>transition.log · 已连接</option><option>reactant.log · 已连接</option></select></label><label>作业<select id="analysis-job"><option value="good">Job 2 · 正常结束</option><option value="empty">Job 1 · 无此类数据</option></select></label></div>`;}
  function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type}));let a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
  function renderLab(){
    const el=$('#lab');if(!el||!chapter)return;
    const id=chapter.id;
    const top=(text)=>`<div class="lab-topline"><span>${text}</span>${badge('示例数据')}</div>`;
    if(id==='project'){
      el.innerHTML=`${top('WORKSPACE / 研究工作区')}<p class="lab-description">先为研究建立一个容器。项目会把日志来源、路径和视图状态组织起来。</p>${button('新建项目','create','primary','file')}<div class="project-preview">${V.icon('network')}<h3>${esc(lab.created?lab.name:'你的下一次发现，从这里开始。')}</h3><p>${lab.created?'一个新的研究工作区已就绪。':'点击上方按钮，创建你的第一个教学项目。'}</p>${lab.created?`<div class="field"><label for="project-name">项目名称</label><input id="project-name" value="${esc(lab.name==='未命名项目'?'':lab.name)}" placeholder="例如：亲核取代反应研究" maxlength="60"></div><div class="control-row">${button('应用名称','name','small')}${button('保存项目','save','primary small','check')}</div>${status(lab.saved?'✓ 教学项目状态已保存 · 实际项目使用 .grproj 文件':'● 未保存 · 先命名，再保存')}</div>`:'</div>'}`;
    }else if(id==='logs'){
      el.innerHTML=`${top('SOURCES / 计算日志')}${button('＋ 导入示例日志','import','primary','file')}<p class="lab-description" style="margin-top:15px">内置合成日志用于练习。实际软件可选择 .log / .out 文件，或导入文件夹。</p>${lab.imported?table(['来源文件','作业','状态'],['reactant.log','transition.log','product.log'].map((name,i)=>`<tr><td>${V.icon('file')} ${name}</td><td>${i===1?'2':'1'} Jobs</td><td class="badge-good">已连接</td></tr>`))+`<div class="control-row"><label>transition.log 的作业<select id="job-select"><option value="1" ${lab.job==='1'?'selected':''}>Job 1 · 未正常结束 · 缺少能量</option><option value="2" ${lab.job==='2'?'selected':''}>Job 2 · 正常结束 · SCF / Freq</option></select></label></div>${lab.job==='2'?`<div class="readout"><div><small>SCF 电子能 · Hartree</small><strong>−99.966000</strong></div>${button('查看来源','evidence','small','code')}</div>`:`<div class="hint-box">这个作业没有可用能量。请选择正常结束且包含所需字段的 Job。</div>`}${lab.evidence?`<div class="log-pre"><span class="line-no">L128</span>SCF Done: E(RB3LYP) = -99.966000 A.U.<br><span class="line-no">Job 2</span>来源：transition.log · 教学模拟核验</div>`:''}`:`<div class="empty-stage">${V.icon('file')}<p>你的计算日志会出现在这里</p><small>先导入，再选择文件与 Job</small></div>`}`;
    }else if(id==='builder'){
      el.innerHTML=`${top('REACTION BUILDER / 物质关系网')}<p class="lab-description">把物质卡加入阶段，再明确角色和组成。可拖动，也可点击加入。</p><div class="species-shelf">${[{id:'r',name:'R · 反应物',file:'reactant.log'},{id:'ts',name:'TS · 过渡态',file:'transition.log'},{id:'p',name:'P · 产物',file:'product.log'}].map(s=>`<div class="species-card" draggable="true" data-species="${s.id}"><span class="species-symbol">${s.id.toUpperCase()}</span><strong>${s.name}</strong><small>${s.file} · Job 2</small><button class="button" data-add-species="${s.id}">＋ 加入阶段</button></div>`).join('')}</div><div id="stage-drop" class="${lab.species.length?'stage-card':'empty-stage'}">${lab.species.length?`<h3>阶段 1 · ${lab.species.map(s=>s.toUpperCase()).join(' + ')}</h3><p>已绑定示例物质来源 · 这里练习一个阶段，实际路径还需多个阶段及明确关系。</p><div class="control-row"><label>角色<select id="stage-role"><option value="">请选择角色</option>${['R','I','TS','P'].map(r=>`<option ${lab.role===r?'selected':''}>${r}</option>`).join('')}</select></label><label>系数<input id="stage-coefficient" type="number" min="0.1" max="10" step=".1" value="${lab.coefficient}" style="width:68px"></label></div>${button('移除物质并重练','clear-stage','small')}`:`${V.icon('network')}<p>将 TS 物质卡放到这里</p><small>或点击卡片上的「加入阶段」</small>`}</div><div class="control-row">${button('预检并保存','preflight','primary','check')}</div><div id="builder-result" class="inline-status" role="status"></div>`;
    }else if(id==='energy'){
      const node=V.nodes[2],ref=lab.reference==='none'?null:V.nodes.find(n=>n.id===lab.reference);let val=M.relativeEnergy((lab.kind==='g'?node.g:node.energy)*lab.coefficient,ref?(lab.kind==='g'?ref.g:ref.energy):null,lab.unit);
      el.innerHTML=`${top('ENERGY EXPRESSION / 体系与参考')}<div class="control-row"><label>能量口径<select id="energy-kind"><option value="scf" ${lab.kind==='scf'?'selected':''}>SCF 电子能 E</option><option value="g" ${lab.kind==='g'?'selected':''}>总自由能 G</option></select></label><label>单位<select id="energy-unit">${['kcal','kj','eh'].map(u=>`<option value="${u}" ${lab.unit===u?'selected':''}>${{kcal:'kcal/mol',kj:'kJ/mol',eh:'Hartree'}[u]}</option>`).join('')}</select></label></div><div class="control-row"><label>路径参考<select id="energy-reference"><option value="none">未设置参考</option><option value="r" ${lab.reference==='r'?'selected':''}>R · 反应物</option><option value="i" ${lab.reference==='i'?'selected':''}>INT · 中间体</option></select></label><label>TS 系数<input id="energy-coefficient" type="number" min=".1" max="3" step=".1" value="${lab.coefficient}" style="width:65px"></label></div><div class="formula-display"><span>${lab.coefficient} × </span>${lab.kind==='g'?'G':'E'}(TS)<br>− ${ref?`${lab.kind==='g'?'G':'E'}(${ref.label})`:'[请选择路径参考]'}<br>──────────────<br>Δ${lab.kind==='g'?'G':'E'} = ${val===null?'等待参考':val.toFixed(lab.unit==='eh'?6:2)} ${lab.unit}</div><div class="hint-box">当前为「体系能量减参考」模式。系数用于表达真实组成，不应为了改变图形随意调整；比较体系应保持化学组成可比。</div>${button('保存表达式','save-expression','primary','check')}${status(lab.expressionSaved?'✓ 示例表达式已显式保存':'核对口径、参考和组成，再保存。')}`;
    }else if(id==='profile'){
      el.innerHTML=`${top('ENERGY PROFILE / 反应能量剖面')}${shared.projectName||shared.recipe?`<div class="hint-box">${esc(shared.projectName||'教学项目')} · ${shared.recipe?'已保存 TS 阶段配方 · ':''}沿用表达式课已保存的口径与单位。当前 ${lab.kind==='g'?'G':'SCF E'} / ${lab.unit}。</div>`:''}<div class="control-row"><label><input type="checkbox" id="compare-path" ${lab.compare?'checked':''}> 路径 B</label><label>颜色 <input id="path-color" type="color" value="${lab.color}" aria-label="路径 B 颜色"></label><div class="segmented"><button class="${lab.dimension==='2d'?'active':''}" data-action="lab-2d">2D</button><button class="${lab.dimension==='3d'?'active':''}" data-action="lab-3d">立体示意</button></div></div><div id="lab-chart">${V.chart(lab)}</div><div class="node-detail" style="margin:0">${detail(lab)}</div><div class="control-row"><label>前驱<select id="precursor"><option value="r">R</option><option value="i">INT</option></select></label><label>过渡态<select id="transition"><option value="i">INT · 非 TS</option><option value="ts">TS</option></select></label>${button('标记势垒','mark-barrier','small')}</div><div id="barrier-result" class="inline-status" role="status"></div>`;
    }else if(['structures','vibrations','thermo','nbo','irc','log'].includes(id)){
      const actions={structures:['读取结构','molecule'],vibrations:['读取频率','wave'],thermo:['读取热化学','thermo'],nbo:['检查 NBO 节','cube'],irc:['读取 IRC 路径','route'],log:['打开所选作业','code']};
      el.innerHTML=`${top('SOURCE-LINKED ANALYSIS / 来源关联分析')}${selector()}<div class="control-row">${button(actions[id][0],'load','primary',actions[id][1])}${lab.loaded?badge('● 示例读取就绪'):''}</div><div id="analysis-body">${lab.loaded?analysisBody(id):`<div class="empty-stage" style="margin-top:24px">${V.icon(actions[id][1])}<p>先选择来源和 Job，再读取</p><small>本页使用合成数据演示；桌面软件会重新检查 SHA-256</small></div>`}</div>`;
      if(lab.loaded&&id==='structures')bindMolecule();
    }else if(id==='tables'){
      el.innerHTML=`${top('PROJECT TABLE / 项目数据表')}<div class="control-row"><input id="table-search" aria-label="筛选节点、来源或路径" placeholder="筛选节点、来源或路径…" value="${esc(lab.query)}" style="flex:1">${button('导出 CSV','csv','small','download')}</div><div id="table-body">${projectTable()}</div><div id="row-detail" class="hint-box">选择结果行，检查路径与来源。数值为教学示例。</div>`;
    }else if(id==='settings'){
      el.innerHTML=`${top('APPEARANCE / 个性化预览')}<div class="control-row"><label>主题<select id="demo-theme"><option value="dark" ${lab.theme==='dark'?'selected':''}>深色</option><option value="light" ${lab.theme==='light'?'selected':''}>浅色</option></select></label><label>语言<select id="demo-language"><option value="zh" ${lab.language==='zh'?'selected':''}>简体中文</option><option value="en" ${lab.language==='en'?'selected':''}>English</option></select></label></div><div class="theme-demo ${lab.theme==='light'?'light':''}"><span class="panel-kicker">GAUSSIANREADERPRO / PREVIEW</span><h3>${lab.language==='zh'?'能量剖面':'Energy Profile'}</h3><p>${lab.language==='zh'?'参考体系：反应物 R · 单位：kcal/mol':'Reference: Reactant R · Unit: kcal/mol'}</p><div class="demo-curve"><svg viewBox="0 0 400 60"><path d="M5 45C55 45 45 25 105 25S150 5 205 5 260 48 300 48 345 40 395 40"/></svg></div></div><label class="switch"><input type="checkbox" id="demo-motion" ${lab.motion?'checked':''}>减少动效（同步本教程背景效果）</label><div class="hint-box">这块预览演示桌面设置的效果。网页音效和背景设置可从本页右上角齿轮单独调整。</div>`;
    }else if(id==='export'){
      const descriptions={png:'PNG：位图展示，适合演示文稿和快速分享。桌面：能量剖面 → 导出 → PNG。',svg:'SVG：可缩放矢量图，适合排版。本页可下载当前教学能量图。',pdf:'PDF：适合报告与矢量排版。桌面：能量剖面 → 导出 → PDF。',html:'离线 HTML：便于交互分享。桌面：能量剖面 → 导出 → 独立 HTML，保留完整输出目录。',csv:'CSV / 审计数据：便于数值核对。本页可下载教学节点数据。',project:'项目 .grproj：用于恢复编辑，不等于自动打包独立来源日志。'};
      el.innerHTML=`${top('EXPORT / 让结果走得更远')}<div class="format-grid">${Object.entries({png:'演示与分享',svg:'矢量排版',pdf:'报告文档',html:'离线交互',csv:'数据与审计',project:'继续编辑'}).map(([key,value])=>`<button class="format-button ${lab.format===key?'active':''}" data-format="${key}">${key==='project'?'.grproj':key.toUpperCase()}<small>${value}</small></button>`).join('')}</div><div class="hint-box">${descriptions[lab.format]}</div><div class="control-row">${button('下载教学 SVG','svg','small','download')}${button('下载教学 CSV','csv','small','table')}</div><div class="field"><label for="recovery-source">来源断开后如何恢复？</label><select id="recovery-source"><option value="changed">同名但内容已变化的日志</option><option value="original" ${lab.recovery==='original'?'selected':''}>指纹一致的原日志</option></select></div>${button('核对来源','recover','primary small','file')}<div id="recovery-status" class="inline-status" role="status"></div>`;
    }
    bindLabChanges();
  }
  function projectTable(){return table(['节点','角色','相对能量 / '+({kcal:'kcal·mol⁻¹',kj:'kJ·mol⁻¹',eh:'Eh'}[lab.unit]),'来源'],V.nodes.filter(n=>(n.label+' '+n.source+' 路径 A').toLowerCase().includes(lab.query.toLowerCase())).map(n=>`<tr data-row="${n.id}" tabindex="0" role="button" aria-label="查看 ${n.label} 来源"><td>${n.label}</td><td>${n.role}</td><td>${currentEnergy(n,lab).toFixed(lab.unit==='eh'?5:2)}</td><td>${n.source}</td></tr>`));}
  function analysisBody(id){
    if(id==='structures')return `<div class="structure-scene" id="molecule-scene">${V.molecule(lab)}<div class="molecule-actions"><button class="button small" data-action="rotate-left" aria-label="向左旋转">↶ 旋转</button><button class="button small" data-action="rotate-right" aria-label="向右旋转">旋转 ↷</button><button class="button small" data-action="zoom-in" aria-label="放大分子">＋</button><button class="button small" data-action="zoom-out" aria-label="缩小分子">−</button><button class="button small" data-action="reset-molecule">复位</button></div></div><div class="hint-box" id="atom-detail">鼠标 / 手指拖动旋转，或用按钮操作。点击原子检查坐标。</div>`;
    if(id==='vibrations')return `<div class="spectrum" aria-label="示例频率谱线">${freqRows.map((r,i)=>`<button data-freq="${i}" style="height:${Math.max(15,r[1]/2.7)}px" aria-label="选择频率 ${r[0]} cm⁻¹"><span>${Math.round(r[0])}</span></button>`).join('')}</div><div class="control-row"><input id="frequency-search" placeholder="筛选频率，例如 426" aria-label="筛选频率" value="${esc(lab.query)}" style="width:100%"></div><div id="frequency-table">${frequencyTable()}</div><div id="frequency-info" class="inline-status" role="status">选择负频率行，核对虚频标记。</div>`;
    if(id==='thermo')return `${table(['字段','读取值','单位','来源行'],thermoRows.map((r,i)=>`<tr data-field="${i}" tabindex="0" role="button" aria-label="解释 ${r[0]}">${r.map(x=>`<td>${x}</td>`).join('')}</tr>`))}<div id="field-info" class="hint-box">点击字段，查看它表示总量还是校正项。</div><div class="control-row"><label>哪一项是总自由能？<select id="thermo-choice"><option value="correction">Gibbs 热校正</option><option value="total">Sum of electronic and thermal Free Energies</option></select></label>${button('核对选择','check-thermo','small')}</div>`;
    if(id==='nbo')return `<div class="control-row"><label>示例格式<select id="nbo-format"><option value="supported" ${lab.nboformat==='supported'?'selected':''}>Gaussian NBO 3.1 · 支持</option><option value="unsupported" ${lab.nboformat==='unsupported'?'selected':''}>不支持格式</option><option value="none" ${lab.nboformat==='none'?'selected':''}>未发现 NBO 节</option></select></label></div>${lab.nboformat==='supported'?`<div class="control-row"><div class="segmented"><button class="${lab.nboTab==='npa'?'active':''}" data-action="npa">NPA 电荷</button><button class="${lab.nboTab==='e2'?'active':''}" data-action="e2">E(2)</button></div><input id="nbo-search" aria-label="筛选 NBO 条目" placeholder="筛选原子，如 O" value="${esc(lab.query)}" style="flex:1"></div><div id="nbo-table">${nboTable()}</div>`:`<div class="hint-box">${lab.nboformat==='unsupported'?'检测到相关节，但当前解析器尚未支持此格式；不会展示猜测结果。':'已核验作业中没有识别到受支持的 NBO 节。'}</div>`}`;
    if(id==='irc')return `<div class="control-row"><label>分支<select id="irc-branch"><option value="forward" ${lab.branch==='forward'?'selected':''}>forward · 正向</option><option value="reverse" ${lab.branch==='reverse'?'selected':''}>reverse · 反向</option></select></label></div><div id="irc-visual">${ircVisual()}</div><div class="field"><label for="irc-point">点序 · 拖动逐点查看</label><input type="range" id="irc-point" min="0" max="5" step="1" value="${lab.point}"></div><div id="irc-table">${ircTable()}</div>`;
    if(id==='log')return `<div class="control-row"><input id="log-search" aria-label="搜索示例日志" placeholder="教学辅助搜索：SCF" value="${esc(lab.query)}" style="flex:1">${button('跳到 L128','line','small')}</div><div class="log-pre" id="log-lines">${logText()}</div><div class="inline-status">Job 2 · L101–L350 · 示例原文，不执行其中内容</div>`;
    return '';
  }
  function frequencyTable(){return table(['频率 / cm⁻¹','IR 强度','状态','来源行'],freqRows.map((r,i)=>({r,i})).filter(({r})=>r.join(' ').includes(lab.query)).map(({r,i})=>`<tr data-freq="${i}" tabindex="0" role="button" aria-label="选择频率 ${r[0]}" class="${lab.freq===i?'selected':''}"><td>${r[0].toFixed(2)}</td><td>${r[1]}</td><td class="${r[0]<0?'badge-warning':'badge-good'}">${r[3]}</td><td>L${r[2]}</td></tr>`));}
  function nboTable(){const rows=lab.nboTab==='npa'?[['C1','-0.120','L402'],['N7','0.510','L408'],['O8','-0.430','L409'],['O9','-0.420','L410']]:[['LP(O8) → BD*(C–N)','6.24','L520'],['LP(O9) → BD*(C–N)','4.18','L521']];return table(lab.nboTab==='npa'?['原子','NPA 电荷 / e','来源行']:['供体 → 受体','E(2) / kcal·mol⁻¹','来源行'],rows.filter(r=>r.join(' ').toLowerCase().includes(lab.query.toLowerCase())).map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`));}
  function ircVisual(){const energy=-lab.point*.002*(lab.branch==='forward'?1:1.1);return `<div class="readout"><div><small>${lab.branch} · Point ${lab.point} · 相对 TS 能量</small><strong>${energy.toFixed(4)} <span style="font-size:12px">Eh</span></strong></div><div style="width:135px;max-height:100px;overflow:hidden">${V.molecule({yaw:.4+lab.point*.18,pitch:.25})}</div></div>`;}
  function ircTable(){return table(['点序','分支','相对 TS / Eh','坐标来源'],Array.from({length:6},(_,i)=>`<tr data-point="${i}" tabindex="0" role="button" aria-label="查看 IRC 点 ${i}" class="${lab.point===i?'selected':''}"><td>${i}</td><td>${lab.branch}</td><td>${(-i*.002*(lab.branch==='forward'?1:1.1)).toFixed(4)}</td><td>L${600+i*30}</td></tr>`));}
  function logText(){return logLines.map(([n,text])=>`<span class="${(lab.query&&text.toLowerCase().includes(lab.query.toLowerCase()))||lab.highlight===n?'highlight':''}"><span class="line-no">L${n}</span>${esc(text)}</span>`).join('\n');}
  function bind(id,event,fn){const el=$('#'+id);if(el)el.addEventListener(event,fn);}
  function bindLabChanges(){
    bind('job-select','change',e=>{lab.job=e.target.value;if(lab.job==='2')act('job','已选择包含目标字段且正常结束的 Job。');renderLab();});
    bind('stage-role','change',e=>{lab.role=e.target.value;if(lab.role==='TS'&&lab.species.includes('ts'))act('role');});
    bind('stage-coefficient','change',e=>{lab.coefficient=Number(e.target.value);});
    bind('energy-kind','change',e=>{lab.kind=e.target.value;lab.expressionSaved=false;if(lab.kind==='g')act('kind');renderLab();});
    bind('energy-reference','change',e=>{lab.reference=e.target.value;lab.expressionSaved=false;if(lab.reference==='r')act('reference');renderLab();});
    bind('energy-unit','change',e=>{lab.unit=e.target.value;renderLab();});
    bind('energy-coefficient','change',e=>{lab.coefficient=Number(e.target.value);lab.expressionSaved=false;renderLab();});
    bind('compare-path','change',e=>{lab.compare=e.target.checked;if(lab.compare)act('compare');renderLab();});
    bind('path-color','input',e=>{lab.color=e.target.value;$('#lab-chart').innerHTML=V.chart(lab);});
    bind('frequency-search','input',e=>{lab.query=e.target.value;$('#frequency-table').innerHTML=frequencyTable();if(lab.query.includes('426'))act('filtered');});
    bind('nbo-search','input',e=>{lab.query=e.target.value;$('#nbo-table').innerHTML=nboTable();if(lab.query.toLowerCase()==='o')act('filtered');});
    bind('nbo-format','change',e=>{lab.nboformat=e.target.value;if(lab.nboformat==='unsupported')act('format');renderLab();});
    bind('table-search','input',e=>{lab.query=e.target.value;$('#table-body').innerHTML=projectTable();if(lab.query.toUpperCase()==='TS')act('filtered');});
    bind('log-search','input',e=>{lab.query=e.target.value;$('#log-lines').innerHTML=logText();if(lab.query.toLowerCase()==='scf')act('searched');});
    bind('irc-branch','change',e=>{lab.branch=e.target.value;if(lab.branch==='reverse')act('branch');$('#irc-visual').innerHTML=ircVisual();$('#irc-table').innerHTML=ircTable();});
    bind('irc-point','input',e=>{lab.point=Number(e.target.value);if(lab.point>0)act('point');$('#irc-visual').innerHTML=ircVisual();$('#irc-table').innerHTML=ircTable();});
    bind('demo-theme','change',e=>{lab.theme=e.target.value;act('theme');renderLab();});
    bind('demo-language','change',e=>{lab.language=e.target.value;if(lab.language==='en')act('language');renderLab();});
    bind('demo-motion','change',e=>{lab.motion=e.target.checked;settings.effects=lab.motion?'light':'full';V.setQuality(settings.effects);persistSettings();act('motion');});
    bind('recovery-source','change',e=>{lab.recovery=e.target.value;});
    bind('analysis-source','change',()=>{lab.loaded=false;$('#analysis-body').innerHTML='<div class="hint-box">来源已切换，请重新读取以核对数据。</div>';});
    bind('analysis-job','change',()=>{lab.loaded=false;$('#analysis-body').innerHTML='<div class="hint-box">作业已切换，请重新读取。</div>';});
    const drop=$('#stage-drop');if(drop){drop.addEventListener('dragover',e=>{e.preventDefault();drop.classList.add('drop-active');});drop.addEventListener('dragleave',()=>drop.classList.remove('drop-active'));drop.addEventListener('drop',e=>{e.preventDefault();const id=e.dataTransfer.getData('text/plain');if(['r','ts','p'].includes(id))addSpecies(id);});}
    $$('[data-species]').forEach(el=>el.addEventListener('dragstart',e=>e.dataTransfer.setData('text/plain',el.dataset.species)));
  }
  function addSpecies(id){if(!lab.species.includes(id))lab.species.push(id);if(id==='ts')act('stage');renderLab();}
  function updateMolecule(){const old=$('#molecule-scene .molecule-svg');if(old){old.outerHTML=V.molecule(lab);bindMolecule();}}
  function bindMolecule(){const svg=$('#molecule-scene .molecule-svg');if(!svg)return;let start=null,moved=false;
    svg.addEventListener('pointerdown',e=>{start={x:e.clientX,y:e.clientY,yaw:lab.yaw,pitch:lab.pitch,id:e.pointerId};moved=false;svg.setPointerCapture(e.pointerId);});
    svg.addEventListener('pointermove',e=>{if(!start)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;if(Math.abs(dx)+Math.abs(dy)>6)moved=true;lab.yaw=start.yaw+dx*.012;lab.pitch=Math.max(-1.2,Math.min(1.2,start.pitch+dy*.012));const html=V.molecule(lab);let next=document.createElement('div');next.innerHTML=html;svg.innerHTML=next.firstElementChild.innerHTML;if(moved)act('rotated');});
    svg.addEventListener('pointerup',e=>{if(!moved){const el=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-atom]');if(el)selectAtom(Number(el.dataset.atom));}start=null;});
    svg.addEventListener('pointercancel',()=>{start=null;});
  }
  function selectAtom(i){lab.atom=i;const a=V.atoms[i];$('#atom-detail').textContent=`原子 ${i+1} · ${a[0]} · x=${a[1].toFixed(4)}, y=${a[2].toFixed(4)}, z=${a[3].toFixed(4)} Å · 教学坐标，来源 L${122+i}`;act('atom');updateMolecule();}
  function renderRoute(){
    const id=location.hash.slice(1)||'overview';
    if(id==='modules'){if(route!=='overview'){location.hash='overview';return;}$('#modules')?.scrollIntoView();return;}
    const next=C.find(c=>c.id===id);route=next?id:'overview';chapter=next||null;step=0;events=new Set();feedback='';lab=freshLab();
    if(chapter){progress.last=chapter.id;if(['profile','tables'].includes(chapter.id)){lab.kind=shared.kind;lab.reference=shared.reference;lab.unit=shared.unit;}save();}nav();topbar();chapter?course():home();$('#sidebar').classList.remove('open');$('#mobile-scrim').classList.remove('active');window.scrollTo(0,0);
  }
  async function action(name){
    if(name==='open-nav'){$('#sidebar').classList.add('open');$('#mobile-scrim').classList.add('active');return;}
    if(name==='close-nav'){$('#sidebar').classList.remove('open');$('#mobile-scrim').classList.remove('active');return;}
    if(name==='search'){showSearch();return;}
    if(name==='preferences'){showPreferences();return;}
    if(name==='audio'){const on=await A.enable(!A.isEnabled());topbar();if(on)A.play('success');toast(on?'音效已开启，轻轻听见每一次探索。':'音效已关闭。');return;}
    if(name==='explore'){$('#modules')?.scrollIntoView({behavior:settings.effects==='off'?'instant':'smooth'});return;}
    if(name==='show-all'){const show=storage.get('showall')!=='yes';storage.set('showall',show?'yes':'no');home();$('#modules').scrollIntoView({block:'start'});return;}
    if(name.startsWith('hero-')){if(name==='hero-compare')hero.compare=!hero.compare;if(name==='hero-2d')hero.dimension='2d';if(name==='hero-3d'){hero.dimension='3d';toast('立体示意仅改变显示角度；不代表真实势能面。');}home();A.play('switch');return;}
    if(name==='restart'){step=0;events.clear();feedback='';lab=freshLab();course();toast('本课练习已重置，已完成的总进度保留。');return;}
    if(name==='next-step'){stepNext();return;}
    if(!chapter)return;
    if(name==='create'){lab.created=true;act('created');renderLab();}
    if(name==='name'){const value=$('#project-name').value.trim();if(!value||/[<>:"/\\|?*]/.test(value)){toast('请输入有效项目名，避免文件名保留字符。');return;}lab.name=value;lab.saved=false;act('named');renderLab();}
    if(name==='save'){if(lab.name==='未命名项目'){toast('先输入项目名称并应用。');return;}lab.saved=true;shared.projectName=lab.name;saveShared();storage.set('sample-project',JSON.stringify({name:lab.name,saved:true}));act('saved');renderLab();toast('教学项目状态已保存；实际软件会生成 .grproj。');}
    if(name==='import'){lab.imported=true;act('imported');renderLab();}
    if(name==='evidence'){lab.evidence=true;act('evidence');renderLab();}
    if(name==='clear-stage'){lab.species=[];lab.role='';events.delete('stage');events.delete('role');events.delete('preflight');renderLab();updateGuide();}
    if(name==='preflight'){const result=M.validateStage(lab);if(!lab.species.includes('ts'))result.errors.push('本课目标是加入 TS 物质');if(lab.role!=='TS')result.errors.push('本课目标阶段角色应为 TS');const valid=result.errors.length===0;$('#builder-result').textContent=valid?'✓ 来源、角色与组成预检通过；教学配方已保存。':result.errors.join('；');if(valid){shared.recipe=true;saveShared();act('preflight');}else{feedback=result.errors[0];updateGuide();}}
    if(name==='save-expression'){if(lab.kind!=='g'||lab.reference!=='r'||!Number.isFinite(lab.coefficient)||lab.coefficient!==1){toast('本课请选择总自由能 G、反应物 R 参考和 TS 系数 1，保持示例体系组成可比。');return;}lab.expressionSaved=true;shared.kind=lab.kind;shared.reference=lab.reference;shared.unit=lab.unit;saveShared();act('expression');renderLab();}
    if(name==='lab-2d'||name==='lab-3d'){lab.dimension=name==='lab-2d'?'2d':'3d';renderLab();if(lab.dimension==='3d')toast('教学立体示意：路径轴是分类，不是势能面。');}
    if(name==='mark-barrier'){const sourceP=V.nodes.find(n=>n.id===$('#precursor').value),sourceTs=V.nodes.find(n=>n.id===$('#transition').value),p={...sourceP,energy:lab.kind==='g'?sourceP.g:sourceP.energy},ts={...sourceTs,energy:lab.kind==='g'?sourceTs.g:sourceTs.energy},value=M.barrier(ts,p,lab.unit);$('#barrier-result').textContent=value===null?'请选择角色为 TS 的节点，以及不同的前驱节点。':`Δ${lab.kind==='g'?'G':'E'}‡ = ${lab.kind==='g'?'G':'E'}(${ts.label}) − ${lab.kind==='g'?'G':'E'}(${p.label}) = ${value.toFixed(lab.unit==='eh'?5:2)} ${{kcal:'kcal/mol',kj:'kJ/mol',eh:'Eh'}[lab.unit]} · 教学示例`;if(value!==null)act('barrier');}
    if(name==='load'){
      if($('#analysis-job').value==='empty'){lab.loaded=false;$('#analysis-body').innerHTML='<div class="hint-box">所选作业没有此类数据。缺失不会补零，请选择包含目标字段的 Job。</div>';return;}
      if($('#analysis-source').selectedIndex!==0){lab.loaded=false;$('#analysis-body').innerHTML='<div class="hint-box">本课程的目标数据位于 transition.log · Job 2。请切回该来源练习；实际软件只展示所选来源真实包含的字段。</div>';return;}
      lab.loaded=true;act('loaded');renderLab();
    }
    if(name==='rotate-left'||name==='rotate-right'){lab.yaw+=name==='rotate-left'?-.35:.35;act('rotated');updateMolecule();}
    if(name==='zoom-in'||name==='zoom-out'){lab.zoom=Math.max(.6,Math.min(1.35,lab.zoom+(name==='zoom-in'?.1:-.1)));updateMolecule();}
    if(name==='reset-molecule'){lab.yaw=.42;lab.pitch=.35;lab.zoom=1;updateMolecule();}
    if(name==='check-thermo'){if($('#thermo-choice').value==='total'){act('thermoquiz');$('#field-info').textContent='✓ 总自由能为电子能与相应热校正之和；示例 -99.966 + 0.045 = -99.921 Eh。';}else $('#field-info').textContent='Gibbs 热校正只是校正项，请选择总自由能字段。';}
    if(name==='npa'||name==='e2'){lab.nboTab=name;lab.query='';renderLab();}
    if(name==='line'){lab.highlight=128;$('#log-lines').innerHTML=logText();act('line');}
    if(name==='csv'){const exportConfig=chapter.id==='tables'?lab:{unit:'kcal',reference:'r',kind:'scf'};const rows=[['教学示例 / node','role','relative_energy_'+exportConfig.unit,'source'],...V.nodes.filter(n=>chapter.id!=='tables'||(n.label+' '+n.source+' 路径 A').toLowerCase().includes(lab.query.toLowerCase())).map(n=>[n.label,n.role,currentEnergy(n,exportConfig),n.source])];download('GaussianReaderPro-教学示例.csv',M.csv(rows),'text/csv;charset=utf-8');act('downloaded');toast('教学 CSV 已下载，数值为合成示例。');}
    if(name==='svg'){let svg=V.chart({selected:'ts'});const css='.axis-label{fill:#7794a3;font-size:9px}.chart-grid{stroke:#abc5cb33;stroke-dasharray:3 5}.energy-curve{fill:none;stroke:#65bda5;stroke-width:2.5}.node-dot{fill:#82d5ba;stroke:#3a726c;stroke-width:2}.node-number,.node-label{fill:#628a84;font-size:10px;text-anchor:middle}.node-hit{fill:transparent}.selected-ring{stroke:#c9a266;fill:#e5ca9922}';svg=svg.replace('<svg ','<svg xmlns="http://www.w3.org/2000/svg" ').replace('<defs>',`<title>GaussianReaderPro 合成教学示例，相对能量单位 kcal/mol</title><style>${css}</style><defs>`);download('GaussianReaderPro-教学示例.svg',svg,'image/svg+xml');act('downloaded');toast('教学 SVG 已下载。');}
    if(name==='recover'){const ok=$('#recovery-source').value==='original';$('#recovery-status').textContent=ok?'✓ 教学核验通过：指纹一致，可以重新连接。':'指纹不匹配：即使同名，内容已改变也不能自动重连。';if(ok)act('recovery');}
  }
  document.addEventListener('click',e=>{
    const actionEl=e.target.closest('[data-action]');if(actionEl){e.preventDefault();void action(actionEl.dataset.action);return;}
    const add=e.target.closest('[data-add-species]');if(add){addSpecies(add.dataset.addSpecies);return;}
    const node=e.target.closest('[data-node]');if(node){if(route==='overview'){hero.selected=node.dataset.node;$('#hero-chart').innerHTML=V.chart(hero);$('#hero-detail').innerHTML=detail(hero);}else if(chapter?.id==='profile'){lab.selected=node.dataset.node;if(lab.selected==='ts')act('node');$('#lab-chart').innerHTML=V.chart(lab);$('.node-detail',$('#lab')).innerHTML=detail(lab);}A.play('click');return;}
    const atom=e.target.closest('[data-atom]');if(atom){if(chapter?.id==='structures'&&lab.loaded)selectAtom(Number(atom.dataset.atom));else if(route==='overview')toast(`示例分子 · ${V.atoms[Number(atom.dataset.atom)][0]} 原子。进入「结构」课可旋转和检查坐标。`);return;}
    const freq=e.target.closest('[data-freq]');if(freq){const i=Number(freq.dataset.freq);lab.freq=i;$('#frequency-table').innerHTML=frequencyTable();$('#frequency-info').textContent=`${freqRows[i][0]} cm⁻¹ · ${freqRows[i][3]} · 来源 L${freqRows[i][2]}。${i===0?'虚频只是 TS 检查线索，还需核对模式。':''}`;if(i===0)act('imaginary');return;}
    const field=e.target.closest('[data-field]');if(field){const i=Number(field.dataset.field);$('#field-info').textContent=[ 'SCF 电子能：电子结构计算的能量，不包含此表中的热校正。','零点能校正：不是总自由能，也不应重复加入已包含它的总量。','Gibbs 热校正：校正项；总自由能需结合对应的电子能。','总自由能 G：对应日志中的电子能与热校正总量。'][i];if(i===2)act('field');return;}
    const point=e.target.closest('[data-point]');if(point){lab.point=Number(point.dataset.point);$('#irc-point').value=lab.point;$('#irc-visual').innerHTML=ircVisual();$('#irc-table').innerHTML=ircTable();if(lab.point>0)act('point');return;}
    const row=e.target.closest('[data-row]');if(row){const n=V.nodes.find(n=>n.id===row.dataset.row);$('#row-detail').textContent=`${n.label} · ${n.role} · 路径 A · 来源 ${n.source} · Job 2 · L128 · ${currentEnergy(n,lab).toFixed(lab.unit==='eh'?5:2)} ${{kcal:'kcal/mol',kj:'kJ/mol',eh:'Eh'}[lab.unit]}（合成示例）`;act('row');return;}
    const format=e.target.closest('[data-format]');if(format){lab.format=format.dataset.format;if(lab.format==='html')act('format');renderLab();return;}
    const quiz=e.target.closest('[data-quiz]');if(quiz){const correct=Number(quiz.dataset.quiz)===chapter.correct;$$('[data-quiz]').forEach(b=>b.classList.remove('correct','wrong'));quiz.classList.add(correct?'correct':'wrong');$('#quiz-result').textContent=correct?'✓ 理解正确，把这个习惯带进真实研究。':'再想一想，可以参考左侧的使用提示。';A.play(correct?'success':'click');}
  });
  document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();showSearch();}if(e.key==='Escape'){action('close-nav');}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-node],[data-atom],[data-freq],[data-field],[data-point],[data-row]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
  $('#mobile-scrim').addEventListener('click',()=>action('close-nav'));
  function showPreferences(){const dialog=$('#preferences');dialog.innerHTML=`<div class="dialog-head"><h2>让探索，更合心意。</h2><button class="icon-button" id="close-preferences" aria-label="关闭设置">${V.icon('close')}</button></div><div class="pref-row"><div><label for="effects-quality">背景与动态效果</label><small>保留毛玻璃材质，自由调整动态程度</small></div><select id="effects-quality"><option value="full" ${settings.effects==='full'?'selected':''}>完整效果</option><option value="light" ${settings.effects==='light'?'selected':''}>轻量 · 少动效</option><option value="off" ${settings.effects==='off'?'selected':''}>关闭动效</option></select></div><div class="pref-row"><div><label for="sound-enabled">交互音效</label><small>柔和的点击、切换与完成音</small></div><input id="sound-enabled" type="checkbox" ${A.isEnabled()?'checked':''} aria-label="开启交互音效"></div><div class="pref-row"><div><label for="sound-volume">音量</label><small>不自动播放背景音乐</small></div><input id="sound-volume" type="range" min="0" max="1" step=".05" value="${settings.volume}"></div><p class="dialog-note">网页只保存本机学习进度与偏好，不会修改桌面软件。声音需要你主动开启。</p><button class="danger-link" id="clear-progress">清空学习进度</button><div id="clear-confirm"></div>`;dialog.showModal();$('#close-preferences').onclick=()=>dialog.close();$('#effects-quality').onchange=e=>{settings.effects=e.target.value;V.setQuality(settings.effects);persistSettings();};$('#sound-enabled').onchange=async e=>{e.target.checked=await A.enable(e.target.checked);topbar();if(e.target.checked)A.play('success');};$('#sound-volume').oninput=e=>{settings.volume=Number(e.target.value);A.setVolume(settings.volume);persistSettings();};$('#clear-progress').onclick=()=>{$('#clear-confirm').innerHTML='<p class="dialog-note">这会清空网页课程完成记录。桌面项目不受影响。</p><button class="button small" id="confirm-reset">确认清空学习记录</button>';$('#confirm-reset').onclick=()=>{progress={done:[],last:C[0].id};save();dialog.close();nav();if(route==='overview')home();toast('学习进度已清空。');};};}
  function showSearch(){const dialog=$('#search-dialog');dialog.innerHTML=`<div class="search-input-wrap">${V.icon('search')}<input id="course-search" placeholder="想学什么？搜索模块、按钮或问题…" aria-label="搜索课程"><button class="icon-button" id="close-search" aria-label="关闭搜索">${V.icon('close')}</button></div><div class="search-results" id="search-results"></div><div class="search-help">输入关键词 · Tab 选择结果 · Esc 关闭</div>`;const render=q=>{$('#search-results').innerHTML=C.filter(c=>[c.short,c.title,c.entry,...c.tips,...c.steps.flat()].join(' ').toLowerCase().includes(q.toLowerCase())).map(c=>`<button class="search-result" data-search-go="${c.id}">${V.icon(c.icon)}<span><strong>${c.short} · ${c.title}</strong><small>${c.entry}</small></span>${V.icon('chevron','chevron')}</button>`).join('')||'<div class="empty-results">没有找到课程，试试“日志”“参考”“导出”。</div>';$$('[data-search-go]').forEach(el=>el.onclick=()=>{dialog.close();go(el.dataset.searchGo);});};render('');dialog.showModal();$('#course-search').focus();$('#course-search').oninput=e=>render(e.target.value);$('#close-search').onclick=()=>dialog.close();}
  for(const dialog of $$('dialog'))dialog.addEventListener('click',e=>{const r=dialog.getBoundingClientRect();if(e.target===dialog&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))dialog.close();});
  window.addEventListener('hashchange',renderRoute);A.setVolume(settings.volume);V.setQuality(settings.effects);renderRoute();
})();
